INSERT INTO `categories` VALUES ('cat_beds','Bedroom','bedroom','Luxury ottoman storage beds, bespoke mirrored wardrobes, handcrafted bedside tables, and deep chests of drawers.','https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1600&q=85','2026-10-15 06:57:21'),('cat_dining','Dining Room','dining','Solid European oak extending dining tables, upholstered velvet chairs, and contemporary breakfast bar stools.','https://images.unsplash.com/photo-1617806118233-18e1de247200?auto=format&fit=crop&w=1600&q=85','2026-10-15 06:57:21'),('cat_living','Living Room','living-room','Architectural coffee tables, high-gloss media consoles, Scandinavian desks, and statement bookcases.','https://images.unsplash.com/photo-1533090161767-e6ffed986c88?auto=format&fit=crop&w=1600&q=85','2026-10-15 06:57:21'),('cat_office','Home Office','home-office','Ergonomic Scandinavian writing desks, executive workstations, and home office bookcases engineered for modern British living.','https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?q=80&w=1600&auto=format&fit=crop','2026-10-15 06:57:21'),('cat_sofas','Sofas & Seating','sofas','Bespoke handcrafted sofas, deep-seated corner groups, and luxury chaises upholstered in durable bouclé and velvet.','https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=1600&q=85','2026-10-15 06:57:21');
