INSERT INTO `customer_reviews` VALUES ('rev_01','prod_live_am_2461','Lady Georgina Sterling (Mayfair, London)','georgina.sterling@mayfair.co.uk',5,'Flawless Sliding Wardrobe & Punctual Delivery','The Madrid sliding door wardrobe fits like a dream in our London apartment. The delivery team were punctual, handled the packaging removal, and the German hardware runs silky smooth.',1,NULL,'approved','2026-10-15 13:38:24'),('rev_02','prod_live_am_3413rz','Dr. Alistair MacLeod (Edinburgh EH1)','alistair.macleod@edinburgh.ac.uk',5,'Superb Artisan Oak Grain & Smooth Runners','The Granada chest of drawers and Louise bedside table have transformed our room. Natural artisan oak grain with premium smooth-glide runners. Pure quality.',1,NULL,'approved','2026-10-15 13:38:24'),('rev_03','prod_live_am_3045rz','Charlotte & David Evans (Harrogate HG1)','charlotte.evans@harrogate.co.uk',5,'Exceptional Mirrored Wardrobe Storage Capacity','The Valentina 220cm sliding wardrobe with full mirror solved our storage problem completely. The mirrored sliding doors feel light and premium, and the interior capacity is exceptional.',1,NULL,'approved','2026-10-15 13:38:24');
