INSERT INTO `products` VALUES ('prod_ftg_1014111','Copenhagen Mirror in Pine','copenhagen-mirror-in-pine','SAN-FTG-1014111','Scandinavian Contemporary - Danish Design by Furniture To Go','<p>Crafted from durable solid pine, this freestanding mirror showcases a timeless, natural aesthetic that complements a wide range of interiors. The warm wood grain finish enhances its classic appeal, while the sturdy frame ensures long-lasting quality and everyday reliability. Designed with practicality in mind, the mirror features a stable base and a smooth tilting mechanism, allowing for easy angle adjustment to suit individual needs. Its compact, self-supporting design makes it ideal for placement on dressing tables, consoles, or bedroom furniture.</p><ul style=\'margin: 1rem 0; list-style: disc;\'><li style=\'margin-left: 1rem;\'>Solid Antique lacquer pine</li><li style=\'margin-left: 1rem;\'>Solid pine frame</li><li style=\'margin-left: 1rem;\'>Adjustable</li></ul><ul style=\'margin: 1rem 0; list-style: disc;\'></ul>','cat_beds','published',27552,34440,20.00,'5060912916839','https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/m/i/mirror_pine_700x700x96dpi.jpg','[\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/m/i/mirror_pine_700x700x96dpi.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/o/copenhagen_single_dressing_table_chair_mirror_700x700x96dpi_1.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/s/c/scandi_double_dressing_table_chair_mirror_700x700x96dpi.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/o/copenhagen_creme_single_dressing_table700x700x96_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/2/0/2012811_3.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/2/0/2012811_5.jpg\"]','[]','2026-10-21 07:11:56','2026-10-27 13:26:16'),('prod_ftg_4029644','Chelsea Bedroom 2 Drawer Bedside in White with a Truffle Oak Trim','chelsea-bedroom-2-drawer-bedside-in-white-with-a-truffle-oak-trim','SAN-FTG-4029644','Scandinavian Contemporary - Danish Design by Furniture To Go','2 drawer bedside in white with an Oak trim. Unconventional design - a proposal for the followers of the latest trends. The clever mix of scratch resistant white melamine with beautiful high gloss fronts and oak melamine trim makes this top quality collection of furniture the ideal destination for the most modern of homes, the massive range that includes many cabinets and wall units fulfils every storage and display option.<ul style=\'margin: 1rem 0; list-style: disc;\'><li style=\'margin-left: 1rem;\'>White high gloss fronts with Oak trim</li><li style=\'margin-left: 1rem;\'>Laminated board (resistant to damage and scratches, moisture and high temperature)</li><li style=\'margin-left: 1rem;\'>Modern handle free solution with soft close</li><li style=\'margin-left: 1rem;\'>Easy self assembly</li></ul><ul style=\'margin: 1rem 0; list-style: disc;\'></ul>','cat_beds','published',27552,34440,20.00,'5060912984770','https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4029644_1.jpg','[\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4029644_1.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4029644_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/402_chelsea_bedroom_3_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4029644_5.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4029644_6.jpg\"]','[]','2026-10-21 07:08:04','2026-10-27 13:26:16'),('prod_ftg_copenhagen_4dr','Copenhagen 4-Drawer Deep Chest in Solid Danish Oak','copenhagen-4-drawer-deep-chest-in-solid-danish-oak','SAN-FTG-CPH-4DR-OAK','Scandinavian minimalism with brushed brass cup handles and smooth metal runners','Crafted in Denmark by Furniture To Go, the Copenhagen 4-Drawer Chest pairs timeless Nordic aesthetics with everyday durability. Featuring deep storage drawers with reinforced bases and precision ball-bearing runners.','cat_beds','published',21900,27900,20.00,'5707310349821','https://images.unsplash.com/photo-1595428774223-ef52624120d2?q=80&w=1200&auto=format&fit=crop','[\"https://images.unsplash.com/photo-1595428774223-ef52624120d2?q=80&w=1200&auto=format&fit=crop\"]',NULL,'2026-10-20 10:54:14','2026-10-27 13:26:16'),('prod_ftg_ftg_par_2d1dr_wht','Paris 2 Door 1 Drawer Wardrobe - Romantic White','paris-2-door-1-drawer-wardrobe-romantic-white','SAN-FTG-PAR-2D1DR-WHT','Paris Collection - Danish Design by Furniture To Go','The Paris 2 Door 1 Drawer Wardrobe brings classic Danish romance into your bedroom. Built with sturdy engineered timber, metal drop handles, and smooth easy-glide metal drawer runners. Certified statutory UK timber compliance.','cat_beds','published',32886,41108,20.00,'5060912929916','https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=1200&q=80','[\"https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=1200&q=80\"]','[]','2026-10-21 06:45:29','2026-10-27 13:26:16'),('prod_ftg_modena_dining','Modena High-Gloss Extending 6-8 Seater Dining Table','modena-high-gloss-extending-6-8-seater-dining-table','SAN-FTG-MOD-DIN-GLS','Centre-leaf butterfly extension mechanism with mirror polished chrome trim','The Modena dining table extends effortlessly from 160cm to 200cm, seating up to 8 dinner guests in style. Engineered with a scratch-resistant Italian UV high-gloss coating.','cat_dining','published',49900,64900,20.00,'5707310349852','https://images.unsplash.com/photo-1617806118233-18e1de247200?q=80&w=1200&auto=format&fit=crop','[\"https://images.unsplash.com/photo-1617806118233-18e1de247200?q=80&w=1200&auto=format&fit=crop\"]',NULL,'2026-10-20 10:54:14','2026-10-27 13:26:16'),('prod_ftg_oslo_desk','Oslo Scandinavian Minimalist Writing Desk with 3 Drawers','oslo-scandinavian-minimalist-writing-desk-with-3-drawers','SAN-FTG-OSL-DSK-ANT','Two-tone anthracite and warm oak finish with recessed cutout handle pulls','Designed for modern home study suites and compact home offices, the Oslo Desk blends functionality with clean Danish lines. Three smooth drawer compartments keep stationary organised.','cat_office','published',24900,31900,20.00,'5707310349845','https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?q=80&w=1200&auto=format&fit=crop','[\"https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?q=80&w=1200&auto=format&fit=crop\"]',NULL,'2026-10-20 10:54:14','2026-10-27 13:26:16'),('prod_ftg_paris_3dr_wardrobe','Paris 3-Door 2-Drawer Classic Mirrored Wardrobe in Matt White','paris-3-door-2-drawer-classic-mirrored-wardrobe-in-matt-white','SAN-FTG-PAR-3DR-WHT','Romantic Parisian styling with decorative cornice moulding and bevelled mirror door','The Paris 3-Door Wardrobe from Furniture To Go infuses Parisian elegance into any master bedroom. Generously proportioned with twin hanging rails, multiple internal shelving nooks, and smooth gliding lower drawers.','cat_beds','published',47900,59900,20.00,'5707310349838','https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=80&w=1200&auto=format&fit=crop','[\"https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=80&w=1200&auto=format&fit=crop\"]',NULL,'2026-10-20 10:54:14','2026-10-27 13:26:16'),('prod_live_am_2394rz','Venice Alpine White Bedside','venice-alpine-white-bedside','SAN-2394','SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days',' In