INSERT INTO `site_page_sections` VALUES ('sec_about_hero','about','about_hero','British Craftsmanship & Heritage',1,1,'{\"eyebrow\":\"Our Heritage & Philosophy\",\"title\":\"Modern Living, Engineered for Everyday Comfort\",\"story\":\"Founded to deliver thoughtfully designed, high-quality home furniture directly to UK doorsteps without inflated retail markups. From sturdy dining sets to modular storage chests and elegant living furniture, every piece is built for real everyday homes.\",\"highlight_stat_1\":\"15,000+ Homes Furnished Across the UK\",\"highlight_stat_2\":\"Rigorous Structural Durability Checks\",\"highlight_stat_3\":\"100% Quality Inspected Prior to Dispatch\"}','2026-10-23 10:46:20'),('sec_about_sustainability','about','about_sustainability','FSC Timber & Ethical Sourcing',1,2,'{\"title\":\"Sustainable Forestry & Responsible Materials\",\"description\":\"We partner exclusively with certified sawmills across Europe and the UK that practice sustainable forestry under strict FSC and PEFC guidelines. Our foams are non-toxic, and our fabrics are free from hazardous fluorocarbons.\",\"bullet_1\":\"FSC-Certified Solid European Oak & American Walnut\",\"bullet_2\":\"Non-toxic high-density reflex foams\",\"bullet_3\":\"Eco-conscious packaging with cardboard recycling collection\"}','2026-10-18 16:39:46'),('sec_account_welcome_banner','account','account_welcome_banner','Client Portal Banner & Privileges',1,1,'{\"welcome_title\":\"SAN Client Portal\",\"welcome_subtitle\":\"Manage your active furniture orders, download official VAT invoices, request swatch samples, and track white-glove dispatches.\",\"vip_perk_badge\":\"UK Verified Client\",\"support_shortcut_text\":\"Need urgent delivery rescheduling? Speak to dispatch directly via our live helpdesk.\"}','2026-10-18 16:39:46'),('sec_cart_threshold_banner','cart','cart_threshold_banner','Free Delivery Progress Bar & Messages',1,1,'{\"threshold_amount_gbp\":500,\"unqualified_message\":\"Free UK Mainland Delivery on all orders!\",\"qualified_message\":\"You have unlocked Free UK White Glove Delivery!\",\"vat_summary_label\":\"Inclusive Transparent UK Pricing\"}','2026-10-22 16:51:03'),('sec_cart_trust_guarantees','cart','cart_trust_guarantees','Cart Drawer Trust Badges',1,2,'{\"guarantees\":[\"Mainland delivery updates sent via SMS & Email\",\"Free Mainland Delivery within 15 days\",\"Dedicated UK concierge assistance for assembly and care instructions\"],\"checkout_button_label\":\"Proceed to Secure UK Checkout\"}','2026-10-22 16:51:03'),('sec_catalog_filter_bar','catalog','catalog_filter_bar','Catalog Filters & Zero State Copy',1,2,'{\"empty_title\":\"No Matching Furniture Pieces Found\",\"empty_description\":\"We could not find any active pieces matching your current facet filters. Please clear one or more criteria to view our available British ranges.\",\"reset_button_label\":\"Clear All Active Filters\",\"sort_options_label\":\"Sort Catalog By\"}','2026-10-18 16:39:46'),('sec_catalog_header','catalog','catalog_header','Catalog Page Banner & Hero Text',1,1,'{\"eyebrow\":\"Architectural Curations\",\"title\":\"The Complete Furniture Collection\",\"subtitle\":\"Explore our full curation of solid hardwood dining sets, textured bouclé sofas, sculptural accent chairs, and ottoman storage beds. Every piece is rigorously tested and delivered direct to your door.\",\"vat_badge\":\"All items include 20% UK VAT with direct delivery tracking\"}','2026-10-18 16:39:46'),('sec_checkout_delivery_guide','checkout','checkout_delivery_guide','Delivery Tiers & Surcharges Guidance',1,2,'{\"standard_tier_title\":\"Standard Tracked Parcel (£9.99 or Free over £100)\",\"pallet_tier_title\":\"Heavy Goods Pallet Delivery (£29.99 or Free over £500)\",\"white_glove_title\":\"Room of Choice White Glove (£49.99 or Free over £500)\",\"surcharge_disclaimer\":\"Deliveries to Scottish Highlands, Isle of Man, and Northern Ireland are subject to automated regional surcharges.\"}','2026-10-20 19:04:05'),('sec_checkout_header_badge','checkout','checkout_header_badge','Safe & Compliant UK Checkout Banner',1,1,'{\"banner_title\":\"Official SAN UK Commerce Gateway\",\"ssl_guarantee\":\"256-Bit Encrypted • PCI-DSS Level 1 Compliant\",\"vat_invoice_claim\":\"A transparent digital order confirmation with full itemised breakdown will be sent upon payment confirmation.\"}','2026-10-23 11:55:28'),('sec_contact_details','contact_faq','contact_details','Concierge Contact & Warehouse Address',1,1,'{\"page_title\":\"Customer Concierge & Support Desk\",\"page_subtitle\":\"Our UK support team is available Monday through Saturday to answer questions regarding orders, product specifications, or room dimensions.\",\"phone\":\"+44 (0) 20 7946 0192\",\"email\":\"concierge@sanfurniture.com\",\"whatsapp\":\"+44 7700 900821\",\"hours\":\"Monday – Friday: 08:30 – 18:30 GMT | Saturday: 09:00 – 16:00 GMT\",\"warehouse_address\":\"SAN Furniture Logistics Hub, Unit 4 Meridian Business Park, Leicester LE19 1RJ, United Kingdom\"}','2026-10-18 16:39:46'),('sec_delivery_tiers_guide','delivery_returns','delivery_tiers_guide','Delivery Tiers & Service Expectations',1,1,'{\"title\":\"Specialist UK Furniture Logistics\",\"lead_time_summary\":\"Mainland UK deliveries are typically completed within 7 to 14 business days. Pre-delivery booking calls are made 48 hours prior to dispatch.\",\"tier_1_title\":\"1. Standard Parcel (Small Items)\",\"tier_1_desc\":\"Tracked next-day courier delivery for lamps, cushions, stools, and care kits.\",\"tier_2_title\":\"2. Heavy Goods Pallet Delivery\",\"tier_2_desc\":\"Kerbside palletized delivery for solid wood dining tables and flatpack modular storage.\",\"tier_3_title\":\"3. Two-Man White Glove Service\",\"tier_3_desc\":\"Delivered into your room of choice, unpackaged, and inspected. Packaging materials are removed for recycling.\"}','2026-10-18 16:39:46'),('sec_faq_list','contact_faq','faq_list','Frequently Asked Questions',1,2,'{\"faqs\":[{\"question\":\"How long does UK delivery take?\",\"answer\":\"Most items are dispatched directly from our UK supplier warehouses within 3-5 business days and delivered to your doorstep within 10-15 business days. You will receive shipment tracking notifications.\"},{\"question\":\"How is my furniture packaged and delivered?\",\"answer\":\"Every piece is carefully boxed in reinforced flat-pack protective packaging with corner buffers, and dispatched directly across Mainland UK within 10-15 business days.\"},{\"question\":\"What delivery service is provided?\",\"answer\":\"We provide free delivery across Mainland UK directly to your doorstep with pre-delivery dispatch updates.\"},{\"question\":\"Will I receive an itemised order receipt?\",\"answer\":\"Yes, an official itemised digital order receipt with complete product codes, quantities, and order reference will be emailed upon payment confirmation.\"}]}','2026-10-23 10:46:20'),('sec_footer_assurance','footer','footer_assurance','4 Pillars of UK Customer Confidence',1,1,'{\"pillars\":[{\"icon\":\"Truck\",\"title\":\"UK Mainland Delivery\",\"description\":\"Direct to your door across the UK Mainland.\"},{\"icon\":\"RotateCcw\",\"title\":\"Free Mainland Delivery\",\"description\":\"Enjoy complimentary delivery across Mainland UK within 15 days.\"},{\"icon\":\"Shield\",\"title\":\"UK Quality Assured\",\"description\":\"High-grade materials and rigorous structural quality testing for long-lasting home durability.\"},{\"icon\":\"Sparkles\",\"title\":\"Secure Card Payments\",\"description\":\"Protected 256-bit SSL encrypted checkout accepting Visa, Mastercard, American Express and Maestro.\"}]}','2026-10-22 16:11:21'),('sec_footer_brand_info','footer','footer_brand_info','Brand Story & UK Customer Care Hours',1,2,'{\"brand_bio\":\"Delivering contemporary home furniture, durable craftsmanship, and dedicated customer support straight to Mainland UK homes.\",\"support_title\":\"Customer Support (UK)\",\"support_hours\":\"Monday – Friday: 09:00 – 18:00 GMT\",\"support_email\":\"support@sanfurniture.com\",\"support_phone\":\"+44 20 7946 0192\",\"legal_note\":\"SAN Furniture UK • Modern Living, Exceptional Quality & Free Mainland Delivery\"}','2026-10-23 11:55:28'),('sec_footer_payment_trust','footer','footer_payment_trust','Payment Trust Badges & Company Number',1,3,'{\"company_number\":\"\",\"copyright_text\":\"© 2026 SAN Furniture. All rights reserved.\",\"positive_copy\":\"SAN Furniture UK • Exceptional Home Living, Premium Quality and Free Mainland Delivery.\",\"accepted_methods\":[\"Visa\",\"Mastercard\",\"American Express\",\"Maestro\"]}','2026-10-23 11:55:28'),('sec_header_main','header','header_main','Header Brand Info & Search Prompt',1,2,'{\"search_placeholder\":\"Search sofas, solid oak dining, ottoman beds...\",\"support_cta_label\":\"Concierge Help\",\"hotline_label\":\"Direct Dispatch Line: +44 20 7946 0192\",\"client_portal_label\":\"Client Account\"}','2026-10-22 16:11:21'),('sec_header_mega_menu','header','header_mega_menu','Desktop & Mobile Mega Menu Navigation',1,3,'{\"tabs\":[{\"id\":\"sofas\",\"label\":\"Sofas & Seating\",\"href\":\"/categories/sofas\",\"badge\":\"\",\"columns\":[{\"title\":\"Sofas By Style\",\"links\":[{\"label\":\"All Sofas & Couches\",\"href\":\"/categories/sofas\"},{\"label\":\"Corner & L-Shape Lounges\",\"href\":\"/categories/sofas?style=corner\",\"badge\":\"HOT\"},{\"label\":\"3-Seater Family Sofas\",\"href\":\"/categories/sofas?seats=3\"},{\"label\":\"2-Seater Compact Sofas\",\"href\":\"/categories/sofas?seats=2\"},{\"label\":\"Modular Sectionals\",\"href\":\"/categories/sofas?type=modular\",\"badge\":\"NEW\"},{\"label\":\"Luxury Sofa Beds\",\"href\":\"/categories/sofas?type=sofa-bed\"}]},{\"title\":\"Chairs & Accents\",\"links\":[{\"label\":\"All Accent Armchairs\",\"href\":\"/categories/armchairs\",\"badge\":\"POPULAR\"},{\"label\":\"Deep-Seat Bouclé Loungers\",\"href\":\"/categories/armchairs?material=boucle\"},{\"label\":\"Matte Velvet Snugglers\",\"href\":\"/catego