INSERT INTO `support_messages` VALUES ('msg_101_1','tick_101','customer',NULL,'Arthur Pendelton','Hello SAN Team, our residence on Kensington Church St has a heritage spiral staircase. Will your white-glove white glove delivery team be able to hoist the sofa or should we arrange the resident service lift in advance?',0,NULL,'2026-10-17 16:47:28'),('msg_102_1','tick_102','customer',NULL,'Lady Beatrice Sterling','We are furnishing our drawing room in Gloucestershire and require physical fabric samples of the Sand Bouclé and Heritage Forest Velvet before placing an order for two armchairs.',0,NULL,'2026-10-17 16:47:28'),('msg_102_2','tick_102','agent',NULL,'Oliver Vance (Senior Concierge)','Dear Lady Beatrice, our upholstery artisans in Long Eaton have prepared a bespoke presentation box with 6 curated fabric samples. They are dispatched today via Royal Mail Special Delivery (Tracking #RM992810UK).',0,NULL,'2026-10-17 16:47:28'),('msg_102_3','tick_102','agent',NULL,'Oliver Vance','Client has an estimated £15,000 project underway with Cotswolds interior architects. Flagged as High Priority VIP.',1,NULL,'2026-10-17 16:47:28'),('msg_103_1','tick_103','customer',NULL,'David Hemmings','Upon unboxing the dining set delivered yesterday, one chair leg had a minor scuff on the solid oak finish. Please advise how to proceed.',0,NULL,'2026-10-17 16:47:28'),('msg_103_2','tick_103','agent',NULL,'Charlotte Davies (Logistics Lead)','Good morning David, we deeply apologize for this imperfection. We have already initiated a replacement leg dispatch directly from our workshop with next-day courier tracking #DX883910. Could you please confirm if the other chairs arrived in pristine condition?',0,NULL,'2026-10-17 16:47:28'),('msg_104_1','tick_104','customer',NULL,'Gemma Collins','Could you please send over the digital PDF assembly instructions for the Oxford Extendable Dining Table?',0,NULL,'2026-10-17 16:47:28'),('msg_104_2','tick_104','agent',NULL,'Oliver Vance','Hi Gemma, the digital CAD assembly guide and torque recommendations have been dispatched to your email. We remain at your disposal should your installers require any further assistance.',0,NULL,'2026-10-17 16:47:28'),('msg_1792238220607_xxmcv','tick_1792238220602_v7pjx','customer',NULL,'Test Verifier','Can the white glove team unpack in second floor master bedroom?',0,NULL,'2026-10-17 16:57:00'),('msg_1792238220626_q1dxn','tick_1792238220602_v7pjx','agent',NULL,'SAN White Glove Lead','Yes absolutely, room-of-choice white-glove clearance is guaranteed for all second floor rooms.',0,NULL,'2026-10-17 16:57:00'),('msg_1792240269436_0v1tx','tick_1792238220602_v7pjx','agent',NULL,'SAN Operations Concierge','Good day, your requested bespoke fabric presentation samples have been carefully prepared and dispatched via Royal Mail 1st Class Signed For. You should receive them within 24–48 hours.',0,NULL,'2026-10-17 17:31:09'),('msg_1792240366265_lo6et','tick_1792238220602_v7pjx','agent',NULL,'SAN Operations Concierge','Hi',0,NULL,'2026-10-17 17:32:46'),('msg_1792241276320_p04jv','tick_1792241276304_et0op','customer',NULL,'Eleanor Vance','This is Test',0,NULL,'2026-10-17 17:47:56'),('msg_1792241299438_ttlyb','tick_1792238220602_v7pjx','agent',NULL,'SAN Operations Concierge','Dear Client, our white-glove White Glove logistics team is scheduled for your area. They will deliver directly to your room of choice, unpack, assemble, and remove all protective packaging. You will receive an SMS 30 minutes before arrival.',0,NULL,'2026-10-17 17:48:19'),('msg_1792241303366_gepd9','tick_103','agent',NULL,'SAN Operations Concierge','Dear Client, our white-glove White Glove logistics team is scheduled for your area. They will deliver directly to your room of choice, unpack, assemble, and remove all protective packaging. You will receive an SMS 30 minutes before arrival.',0,NULL,'2026-10-17 17:48:23'),('msg_1792246009727_a9mtk','tick_101','agent',NULL,'SAN Operations Concierge','Your pallet consignment is currently in transit with DX Freight. You can monitor live tracking using your consignment number on the carrier portal or through your SAN Client Portal.',0,NULL,'2026-10-17 19:06:49'),('msg_1792315047524_gpcoc','tick_1792241276304_et0op','customer',NULL,'Eleanor','Hi',0,NULL,'2026-10-18 14:17:27'),('msg_1792315062659_xtyia','tick_1792241276304_et0op','agent',NULL,'SAN Operations Concierge','Hello',0,NULL,'2026-10-18 14:17:42');
