INSERT IGNORE INTO `products` (
  `id`, `handle`, `sku`, `title`, `subtitle`, `description`, `category_id`, `status`, `price_pennies`, `compare_at_price_pennies`, `cost_price_pennies`, `vat_rate_percent`, `gtin_barcode`, `thumbnail_url`, `images_json`, `variants_json`, `created_at`, `updated_at`
) VALUES 
  ('prod_ftg_1014111', 'copenhagen-mirror-in-pine', 'SAN-1014111', 'Copenhagen Mirror in Pine', 'Scandinavian Contemporary - Danish Design by Furniture To Go', 'Crafted from durable solid pine, this freestanding mirror showcases a timeless, natural aesthetic that complements a wide range of interiors. The warm wood grain finish enhances its classic appeal, while the sturdy frame ensures long-lasting quality and everyday reliability. Designed with practicality in mind, the mirror features a stable base and a smooth tilting mechanism, allowing for easy angle adjustment to suit individual needs. Its compact, self-supporting design makes it ideal for placement on dressing tables, consoles, or bedroom furniture.\n\n• Solid Antique lacquer pine\n• Solid pine frame\n• Adjustable', 'cat_beds', 'published', 13440, 16800, NULL, '20.00', '5060912916839', 'https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/m/i/mirror_pine_700x700x96dpi.jpg', '[\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/m/i/mirror_pine_700x700x96dpi.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/o/copenhagen_single_dressing_table_chair_mirror_700x700x96dpi_1.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/s/c/scandi_double_dressing_table_chair_mirror_700x700x96dpi.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/o/copenhagen_creme_single_dressing_table700x700x96_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/2/0/2012811_3.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/2/0/2012811_5.jpg\"]', '[]', '2026-10-21 07:11:56', '2026-10-29 12:35:37'),
  ('prod_ftg_4023544', 'chelsea-living-1-drawer-2-door-sideboard-in-white-with-a-truffle-oak-trim', NULL, 'Chelsea Living 1 Drawer 2 Door Sideboard in White with a Truffle Oak Trim', 'Scandinavian Contemporary - Danish Design by Furniture To Go', '1 drawer 2 door sideboard in white with an Truffle Oak trim. Unconventional design a proposal for the followers of the latest trends. The clever mix of scratch resistant white melamine with beautiful high gloss fronts and oak melamine trim makes this top quality collection of furniture the ideal destination for the most modern of homes, the massive range that includes many cabinets and wall units fulfils every storage and display option.\n\nWhite high gloss fronts with Oak trim\n\nLaminated board (resistant to damage and scratches, moisture and high temperature)\n\nModern handle free solution with soft close\n\nEasy self assembly', 'cat_living', 'published', 26040, 32550, NULL, '20.00', '5060912999841', 'https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4023544_1.jpg', '[\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4023544_1.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4023544_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/402_chelsea_dining_room_2_1000x1000_3.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/402_chelsea_wardrobe_3_1000x1000_1_3.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/h/chelsea_detail8_1000x1000_12.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/h/chelsea_detail7_1000x1000_8.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/h/chelsea_white_melamine_40.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/c/h/chelsea_truffel_oak_melamine_38.jpg\"]', NULL, '2026-10-29 05:44:58', '2026-10-29 05:44:58'),
  ('prod_ftg_4025544', 'chelsea-living-wide-tv-unit-in-white-with-a-truffle-oak-trim', 'SAN-4025544', 'Chelsea Living Wide TV Unit in White with a Truffle Oak Trim', 'Scandinavian Contemporary - Contemporary Scandinavian Design', 'Wide TV unit in white with an Truffle Oak trim. Unconventional design - a proposal for the followers of the latest trends. The clever mix of scratch resistant white melamine with beautiful high gloss fronts and oak melamine trim makes this top quality collection of furniture the ideal destination for the most modern of homes, the massive range that includes many cabinets and wall units fulfils every storage and display option.\n• White high gloss fronts with Oak trim\n• Laminated board (resistant to damage and scratches, moisture and high temperature)\n• Modern handle free solution with soft close\n• Easy self assembly', 'cat_living', 'published', 26040, 32550, NULL, '20.00', '5060912959941', 'https://furniture-to-go.co.uk/media/catalog/product/4/0/4025544_1.jpg', '[\"https://furniture-to-go.co.uk/media/catalog/product/4/0/4025544_1.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4025544_1.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/4/0/4025544_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4025544_2.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/4/0/4025544_4.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4025544_4.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/4/0/4025544_3.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4025544_3.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/4/0/4025544_5.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/cache/384edea40d4e170da5e8c6dc52ed3beb/4/0/4025544_5.jpg\",\"https://furniture-to-go.co.uk/media/catalog/product/c/h