  ('prod_ftg_copenhagen_4dr', 'copenhagen-4-drawer-deep-chest-in-solid-danish-oak', 'SAN-CPH-4DR-OAK', 'Copenhagen 4-Drawer Deep Chest in Solid Danish Oak', 'Scandinavian minimalism with brushed brass cup handles and smooth metal runners', 'Crafted in Denmark by Furniture To Go, the Copenhagen 4-Drawer Chest pairs timeless Nordic aesthetics with everyday durability. Featuring deep storage drawers with reinforced bases and precision ball-bearing runners.', 'cat_beds', 'published', 21900, 27900, NULL, '20.00', '5707310349821', 'https://images.unsplash.com/photo-1595428774223-ef52624120d2?q=80&w=1200&auto=format&fit=crop', '[\"https://images.unsplash.com/photo-1595428774223-ef52624120d2?q=80&w=1200&auto=format&fit=crop\"]', NULL, '2026-10-20 10:54:14', '2026-10-28 06:00:50'),
  ('prod_ftg_ftg_lyon_med_5443', 'lyon-medium-extending-dining-table-140-180-cm-in-riviera-oak-white-high-gloss', NULL, 'Lyon Medium Extending Dining Table 140 180 Cm In Riviera Oak White High Gloss', 'Scandinavian Range - Danish Design by Furniture To Go', 'High quality Scandinavian flat-pack furniture manufactured to European standards. Distributed via Furniture To Go Wiltshire logistics hub.', 'cat_dining', 'published', 25032, 31290, NULL, '20.00', '5060912985446', 'https://images.unsplash.com/photo-1595428774223-ef52624120d2', '[\"https://images.unsplash.com/photo-1595428774223-ef52624120d2\"]', NULL, '2026-10-29 05:44:58', '2026-10-29 12:35:35'),
  ('prod_ftg_ftg_par_2d1dr_wht', 'paris-2-door-1-drawer-wardrobe-romantic-white', 'SAN-PAR-2D1DR-WHT', 'Paris 2 Door 1 Drawer Wardrobe - Romantic White', 'Paris Collection - Danish Design by Furniture To Go', 'The Paris 2 Door 1 Drawer Wardrobe brings classic Danish romance into your bedroom. Built with sturdy engineered timber, metal drop handles, and smooth easy-glide metal drawer runners. Certified statutory UK timber compliance.', 'cat_beds', 'published', 32886, 41108, NULL, '20.00', '5060912929916', 'https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=1200&q=80', '[\"https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=1200&q=80\"]', '[]', '2026-10-21 06:45:29', '2026-10-28 06:00:50'),
  ('prod_ftg_modena_dining', 'modena-high-gloss-extending-6-8-seater-dining-table', 'SAN-MOD-DIN-GLS', 'Modena High-Gloss Extending 6-8 Seater Dining Table', 'Centre-leaf butterfly extension mechanism with mirror polished chrome trim', 'The Modena dining table extends effortlessly from 160cm to 200cm, seating up to 8 dinner guests in style. Engineered with a scratch-resistant Italian UV high-gloss coating.', 'cat_dining', 'published', 49900, 64900, NULL, '20.00', '5707310349852', 'https://images.unsplash.com/photo-1617806118233-18e1de247200?q=80&w=1200&auto=format&fit=crop', '[\"https://images.unsplash.com/photo-1617806118233-18e1de247200?q=80&w=1200&auto=format&fit=crop\"]', NULL, '2026-10-20 10:54:14', '2026-10-28 06:00:50'),
  ('prod_ftg_oslo_desk', 'oslo-scandinavian-minimalist-writing-desk-with-3-drawers', 'SAN-OSL-DSK-ANT', 'Oslo Scandinavian Minimalist Writing Desk with 3 Drawers', 'Two-tone anthracite and warm oak finish with recessed cutout handle pulls', 'Designed for modern home study suites and compact home offices, the Oslo Desk blends functionality with clean Danish lines. Three smooth drawer compartments keep stationary organised.', 'cat_office', 'published', 24900, 31900, NULL, '20.00', '5707310349845', 'https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?q=80&w=1200&auto=format&fit=crop', '[\"https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?q=80&w=1200&auto=format&fit=crop\"]', NULL, '2026-10-20 10:54:14', '2026-10-28 06:00:50'),
  ('prod_ftg_paris_3dr_wardrobe', 'paris-3-door-2-drawer-classic-mirrored-wardrobe-in-matt-white', 'SAN-PAR-3DR-WHT', 'Paris 3-Door 2-Drawer Classic Mirrored Wardrobe in Matt White', 'Romantic Parisian styling with decorative cornice moulding and bevelled mirror door', 'The Paris 3-Door Wardrobe from Furniture To Go infuses Parisian elegance into any master bedroom. Generously proportioned with twin hanging rails, multiple internal shelving nooks, and smooth gliding lower drawers.', 'cat_beds', 'published', 47900, 59900, NULL, '20.00', '5707310349838', 'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=80&w=1200&auto=format&fit=crop', '[\"https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=80&w=1200&auto=format&fit=crop\"]', NULL, '2026-10-20 10:54:14', '2026-10-28 06:00:50'),
  ('prod_live_am_2394rz', 'venice-alpine-white-bedside', 'SAN-2394', 'Venice Alpine White Bedside', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', ' Introducing the Venice Alpine White Bedside Table. This elegant piece features three spacious drawers, perfect for keeping your night time essentials organised and within reach. The sleek alpine white finish adds a touch of modern sophistication to your bedroom decor. Functional and stylish, this bedside table is the ideal addition to complete your bedroom setup. Alpine White All 3 Drawers On Metal Runners Size W45cm, H58cm, D40cm Dispatch Time 2-5 Days DHD Service Available ', 'cat_beds', 'published', 11046, 13808, NULL, '20.00', '5060912802394', 'https://files.ekmcdn.com/amosmann1/images/venice-alpine-white-bedside-2394-2394-p.jpg', '[\"https://files.ekmcdn.com/amosmann1/images/venice-alpine-white-bedside-2394-2394-p.jpg\"]', '[]', '2026-10-17 06:18:46', '2026-10-29 05:47:46'),
  ('prod_live_am_2413rz', 'louise-white-gloss-bedside-table', 'SAN-2413', 'Louise White Gloss Bedside Table', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', '\b The Louise White Gloss Bedside Table with 2 Drawers boasts both style and functionality. Featuring smooth glide metal runners, all drawers open effortlessly for easy access to your essentials. Its sleek white gloss finish adds a modern touch to any bedroom decor, making it a stylish and practical addition to your bedside ensemble. White Gloss Drawer Fronts and Top With Matt White Sides 2 Drawers All Drawers on Smooth Glide Metal Runners Flat Packed Size: Width 41.8cm, Height 55.7cm, Depth 42.2cm Also Available in White Gloss Dispatch Time: 2-3 days DHD Service Available', 'cat_beds', 'published', 7813, 9766, NULL, '20.00', '5060912802413', 'https://files.ekmcdn.com/amosmann1/images/louise-white-gloss-bedside-table-2413-2413-p.jpg', '[\"https://files.ekmcdn.com/amosmann1/images/louise-white-gloss-bedside-table-2413-2413-p.jpg\"]', '[]', '2026-10-17 06:59:17', '2026-10-29 05:47:46'),
  ('prod_live_am_2428', 'madrid-wardrobe-internal-drawers', 'SAN-2428', 'Madrid Wardrobe Internal Drawers', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', 'Maximise wardrobe space with these efficient storage solutions for clothes and accessories. The neutral design complements any wardrobe style, featuring 3 drawers for easy organisation and access. Crafted with sturdy construction, these drawers promise long-lasting durability. Alpine White All 3 Drawers On Metal Runners Size W60cm, H57cm, D44cm Dispatch Time 2-5 Days DHD Service Available Total Packages 1 Weight 20kg', 'cat_beds', 'published', 5742, 7178, NULL, '20.00', '5060912802428', 'https://files.ekmcdn.com/amosmann1/images/madrid-wardrobe-internal-drawers-2428-2428-p.jpg', '[\"https://files.ekmcdn.com/amosmann1/images/madrid-wardrobe-internal-drawers-2428-2428-p.jpg\",\"https://files.ekmcdn.com/amosmann1/images/madrid-wardrobe-internal-drawers-2428-(2)-2428-p.jpg\"]', '[]', '2026-10-17 07:04:46', '2026-10-29 05:47:46'),
  ('prod_live_am_2429', 'madrid-white-gloss-tall-chest-of-drawers', 'SAN-2429', 'Madrid White Gloss Tall Chest Of Drawers', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', 'Elevate your bedroom with the sleek Madrid White Gloss Tall Chest of Drawers. Featuring four spacious drawers, this elegant piece offers ample storage while its glossy finish adds a touch of modern sophistication. Perfect for organising clothes and accessories, its sturdy construction ensures lasting durability. Available in White Gloss Effect Smooth Glide Drawer Runners Flat Packed W60cm, H109cm, D38cm Dispatched in 2-3 days', 'cat_living', 'published', 14094, 17618, NULL, '20.00', '5060912802429', 'https://files.ekmcdn.com/amosmann1/images/madrid-white-gloss-tall-chest-of-drawers-2429-2429-p.png', '[\"https://files.ekmcdn.com/amosmann1/images/madrid-white-gloss-tall-chest-of-drawers-2429-2429-p.png\",\"https://files.ekmcdn.com/amosmann1/images/madrid-white-gloss-tall-chest-of-drawers-2429-(2)-2429-p.jpg\"]', '[]', '2026-10-17 13:13:52', '2026-10-29 05:46:30'),
  ('prod_live_am_2439', 'zing-white-gloss-bookcase', 'SAN-2439', 'Zing White Gloss Bookcase', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', '\b Introducing the Zing White Gloss Tall Bookcase, a sleek and functional piece for modern interiors. This bookcase features 6 open storage compartments, offering ample space to display books, decor, and personal items. The white gloss finish adds a contemporary touch, making it a versatile addition to living rooms, offices, or studies. Organise and showcase your belongings stylishly with the Zing Tall Bookcase, perfect for both storage and aesthetic appeal in your home. White gloss Suitable for any room Delivered flat Packed Size: H192cm, W80cm, D25cm Dispatched in 2-3 days', 'cat_living', 'published', 11484, 14355, NULL, '20.00', '5060912802439', 'https://files.ekmcdn.com/amosmann1/images/zing-white-gloss-bookcase-2439-2439-p.png', '[\"https://files.ekmcdn.com/amosmann1/images/zing-white-gloss-bookcase-2439-2439-p.png\",\"https://files.ekmcdn.com/amosmann1/images/zing-white-gloss-bookcase-2439-(2)-2439-p.jpg\",\"https://files.ekmcdn.com/amosmann1/images/zing-white-gloss-bookcase-2439-(3)-2439-p.jpg\",\"https://files.ekmcdn.com/amosmann1/images/zing-white-gloss-bookcase-2439-(4)-2439-p.jpg\",\"https://files.ekmcdn.com/amosmann1/images/zing-white-gloss-bookcase-2439-(5)-2439-p.jpg\"]', '[]', '2026-10-17 13:13:53', '2026-10-27 13:26:16'),
  ('prod_live_am_2444', 'mila-artic-white-bookcase', 'SAN-2444', 'Mila Artic White Bookcase', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', 'Enhance your home with the sleek Mila Arctic White Bookcase, featuring five open storage compartments. Perfect for displaying books, decor, or collectibles, its minimalist design adds a touch of elegance to any room. The sturdy construction ensures durability, making it a stylish and practical addition to your space. Artic White Suitable for any room Delivered flat Packed Size: H180cm, W52cm, D25cm Dispatched in 2-3 days', 'cat_living', 'published', 6960, 8700, NULL, '20.00', '5060912802444', 'https://files.ekmcdn.com/amosmann1/images/mila-artic-white-bookcase-2444-2444-p.png', '[\"https://files.ekmcdn.com/amosmann1/images/mila-artic-white-bookcase-2444-2444-p.png\",\"https://files.ekmcdn.com/amosmann1/images/mila-artic-white-bookcase-2444-(2)-2444-p.jpg\"]', '[]', '2026-10-18 09:33:56', '2026-10-27 13:26:16'),
  ('prod_live_am_2458', 'belas-white-gloss-tv-complete-wall-cabinet', 'SAN-2458', 'Belas White Gloss TV Complete Wall Cabinet', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', 'The Belas White Gloss TV Cabinet with Wall Unit is designed to accommodate TVs up to 50 inches, offering both style and functionality. This set includes a wall-mounted shelf and cupboard, providing additional storage space for media accessories and décor. With its sleek white gloss finish, it adds a touch of modern elegance to any living space while keeping your entertainment area organised and clutter-free. White gloss With Anthracite Gloss Inserts Will hold up to 50\" TV Shelves, cupboard and floor cabinet included Floor cabinet height 45cm W200cm, D41cm Delivered flat Packed', 'cat_living', 'published', 18966, 23708, NULL, '20.00', '5060912802458', 'https://files.ekmcdn.com/amosmann1/images/belas-white-gloss-tv-complete-wall-cabinet-2458-2458-p.jpg', '[\"https://files.ekmcdn.com/amosmann1/images/belas-white-gloss-tv-complete-wall-cabinet-2458-2458-p.jpg\"]', '[]', '2026-10-18 09:33:57', '2026-10-27 13:26:16'),
  ('prod_live_am_2461', 'madrid-sliding-door-wardrobe-120cm-gloss-white', 'SAN-2461', 'Madrid Sliding Door Wardrobe 120cm Gloss White', 'SAN Furniture Luxury Collection - Dispatch Time 2-7 Business Days', ' The Madrid Sliding Door Wardrobe in Soft Gloss White (120cm) offers both style and functionality for your bedroom. With its sleek design and glossy finish, it adds a modern touch to any space. Inside, you\'ll find five internal storage compartments and a hanging rail, providing ample room for organising your clothes and accessories. The sliding doors make it space-efficient, perfect for smaller rooms. Available in White Soft Gloss Effect  Shelves and hanging rails included Flat Packed Size W120cm, H200cm, D50cm Dispatch Time 7-10 Days DHD Service Available ', 'cat_beds', 'published', 25752, 32190, NULL, '20.00', '5060912802461', 'https://files.ekmcdn.com/amosmann1/images/madrid-sliding-door-wardrobe-120cm-gloss-white-2461-2461-p.png', '[\"https://files.ekmcdn.com/amosmann1/images/madrid-sliding-door-wardrobe-120cm-gloss-white-2461-2461-p.png\",\"https://files.ekmcdn.com/amosmann1/images/madrid-sliding-door-wardrobe-120cm-gloss-white-2461-(2)-2461-p.jpg\",\"https://files.ekmcdn.com/amosmann1/images/madrid-sliding-door-wardrobe-120cm-gloss-white-2461-(3)-2461-p.png\"]', '[]', '2026-10-17 06:18:44', '2026-10-27 13:26:16'),
